23	/**
24	 * Turns the cart into an order in one transaction: locks the cart and its products,
25	 * checks stock, decrements it and removes the ordered lines. Returns the new order id.
26	 */
27	export async function placeOrder(
28	  db: Db,
29	  cartId: string | undefined,
30	  settings: ShopSettings,
31	): Promise<number> {
32	  if (!settings.checkoutEnabled) throw new ShopError('checkout_disabled', 'Checkout is paused');
33	  if (!cartId) throw new ShopError('empty_cart', 'Cart is empty');
34	
35	  return db.transaction(async (tx) => {
36	    // Without this, a double-submitted checkout reads the same lines twice and orders them twice.
37	    if (!(await lockCart(tx, cartId))) throw new ShopError('empty_cart', 'Cart is empty');
38	    const { rows: lines } = await tx.query<OrderItem & { stock: number }>(
39	      `select p.id as "productId", p.name, p.stock, p.price_cents as "unitPriceCents", ci.quantity
40	       from cart_items ci join products p on p.id = ci.product_id
41	       where ci.cart_id = $1
42	       order by p.id
43	       for update of p`,
44	      [cartId],
45	    );
46	    if (lines.length === 0) throw new ShopError('empty_cart', 'Cart is empty');
47	    const short = lines.find((line) => line.quantity > line.stock);
48	    if (short) throw new ShopError('out_of_stock', `Only ${short.stock} ${short.name} left`);
49	
50	    const subtotalCents = lines.reduce((sum, l) => sum + l.unitPriceCents * l.quantity, 0);
51	    const shippingCents = shippingFor(subtotalCents, settings);
52	    const { rows } = await tx.query<{ id: number }>(
53	      `insert into orders (subtotal_cents, shipping_cents, total_cents)
54	       values ($1, $2, $3) returning id`,
55	      [subtotalCents, shippingCents, subtotalCents + shippingCents],
56	    );
57	    const orderId = rows[0]!.id;
58	
59	    for (const line of lines) {
60	      await tx.query(
61	        `insert into order_items (order_id, product_id, quantity, unit_price_cents)
62	         values ($1, $2, $3, $4)`,
63	        [orderId, line.productId, line.quantity, line.unitPriceCents],
64	      );
65	      await tx.query('update products set stock = stock - $1 where id = $2', [
66	        line.quantity,
67	        line.productId,
68	      ]);
69	    }
70	    await tx.query('delete from cart_items where cart_id = $1 and product_id = any($2::int[])', [
71	      cartId,
72	      lines.map((line) => line.productId),
73	    ]);
74	    return orderId;
75	  });
76	}
