78	export async function getOrder(db: Queryable, id: number): Promise<Order | null> {
79	  const { rows } = await db.query<Omit<Order, 'items'>>(
80	    `select id, status, subtotal_cents as "subtotalCents", shipping_cents as "shippingCents",
81	            total_cents as "totalCents", created_at as "createdAt"
82	     from orders where id = $1`,
83	    [id],
84	  );
85	  const order = rows[0];
86	  if (!order) return null;
87	
88	  const { rows: items } = await db.query<OrderItem>(
89	    `select oi.product_id as "productId", p.name, oi.quantity, oi.unit_price_cents as "unitPriceCents"
90	     from order_items oi join products p on p.id = oi.product_id
91	     where oi.order_id = $1
92	     order by p.name`,
93	    [id],
94	  );
95	  return { ...order, items };
96	}

