10	export async function testShop(overrides: Partial<ShopSettings> = {}): Promise<TestShop> {
11	  const jar = new Map<string, string>();
12	  const cookies = {
13	    get: (name: string) => (jar.has(name) ? { name, value: jar.get(name) } : undefined),
14	    set: (name: string, value: string) => void jar.set(name, value),
15	  } as unknown as CookieStore;
