19	/** Awaits a call that should end in `redirect()` or `notFound()` and returns where it went. */
20	export async function navigation(work: Promise<unknown>): Promise<string> {
21	  try {
22	    await work;
23	  } catch (err) {
24	    const digest = (err as { digest?: string }).digest ?? '';
25	    if (digest.startsWith('NEXT_REDIRECT')) return digest.split(';')[2] ?? '';
26	    if (digest === 'NEXT_HTTP_ERROR_FALLBACK;404') return 'not-found';
27	    throw err;
28	  }
29	  throw new Error('expected a redirect or notFound');
